{
  "identity": {
    "name": "Boise Metal Works",
    "location": "Boise, Idaho",
    "claims": [
      {
        "statement": "Boise Metal Works is a custom metal fabrication and manufacturing business located in Boise, Idaho.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/",
        "quote": "Boise Metal Works provides custom metal fabrication and manufacturing solutions for commercial, industrial, and residential applications."
      },
      {
        "statement": "The physical facility is located at 2000 Yamhill Rd., Boise, ID 83716.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/",
        "quote": "2000 Yamhill Rd. Boise, ID 83716"
      },
      {
        "statement": "The business traces its origins to 1994 when it was founded in Idaho.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/idaho-master-metal-fabricators-history/",
        "quote": "Since 1994 Boise Metal Works has grown from an idea to a well-rounded industry leader that prides itself on the knowledge and expertise"
      }
    ]
  },
  "industry": {
    "industry": "Custom Metal Fabrication and Manufacturing",
    "activities": [
      "Custom metal fabrication (carbon steel, stainless steel, and aluminum)",
      "Architectural and structural metalwork (railings, stairs, gates, fences, and awnings)",
      "CNC machining and CNC water jet cutting",
      "Steel shearing, forming, rolling, and saw cutting",
      "Shop and field welding (hardwire, dual shield, TIG, and stick)",
      "Truck accessories, upfitting, and steel tank fabrication",
      "Product development and value engineering for contractors and entrepreneurs",
      "In-house painting and coordination of local powder coating"
    ],
    "claims": [
      {
        "statement": "The company provides custom metal fabrication and manufacturing across commercial, industrial, and residential sectors.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/",
        "quote": "Boise Metal Works provides custom metal fabrication and manufacturing solutions for commercial, industrial, and residential applications."
      },
      {
        "statement": "Boise Metal Works provides value engineering and metal manufacturing support to general contractors and entrepreneurs.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/product-development-manufacturing/",
        "quote": "Boise Metal Works provides value engineering services to General Contractors and entrepreneurs which allows for options within the metal fabrication work scope"
      },
      {
        "statement": "Boise Metal Works operates as a specialized job shop and metal manufacturer rather than a residential HVAC, plumbing, or electrical trade contractor.",
        "label": "inference",
        "sourceUrl": "https://www.boisemetalworks.com/metal-fabrication-shop-capacities/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://www.boisemetalworks.com/",
    "claims": [
      {
        "statement": "Boise Metal Works maintains an official website designed by Thrive Web Designs.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/",
        "quote": "©2026 Boise Metal Works, All Rights Reserved. Website Design Boise by Thrive Web Designs"
      },
      {
        "statement": "The business operates a standard shop labor billing rate of $95 per hour.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/metals-fabrication-industry-infomation/",
        "quote": "Our shop rate is $95 an hour and is subject to change. This is separate from our machining and water jet rates."
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The company complies with commercial and residential building codes for architectural fabrications such as stair rise and handrail dimensions.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/metals-fabrication-industry-infomation/",
        "quote": "Maximum rise is 7″ per commercial code 7 1/4″ per residential code."
      },
      {
        "statement": "No specific Idaho state contractor registration numbers or business filing IDs are published on the website pages.",
        "label": "inference",
        "sourceUrl": "https://www.boisemetalworks.com/contact/",
        "quote": null
      }
    ],
    "limitations": "The public website does not display Idaho public works licenses, contractor registration numbers, or corporate entity filing numbers."
  },
  "existingSoftware": [
    {
      "product": "Geometric Nesting Software",
      "purpose": "Optimizing sheet material utilization for the CNC water jet cutting system.",
      "evidence": {
        "statement": "Boise Metal Works uses specialized software to nest cut parts efficiently.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/metal-fabrication-shop-capacities/",
        "quote": "our software allows us to geometrically nest parts to utilize material to its fullest extent."
      }
    },
    {
      "product": "Contact Form 7 with Google reCAPTCHA",
      "purpose": "Capturing web inquiries and customer design file attachments.",
      "evidence": {
        "statement": "The website provides an online intake form supporting design file uploads up to 16MB.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/contact/",
        "quote": "Upload your Idea Here (16M Max)"
      }
    },
    {
      "product": "Google Tag Manager / Google Analytics",
      "purpose": "Website visitor and marketing tag measurement.",
      "evidence": {
        "statement": "Google Tag Manager is integrated into the site's code for tracking.",
        "label": "inference",
        "sourceUrl": "https://www.boisemetalworks.com/",
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "Each project is managed directly by an individual dedicated contact throughout its lifecycle.",
      "label": "fact",
      "sourceUrl": "https://www.boisemetalworks.com/",
      "quote": "Your dedicated, Boise Metal Works point of contact is committed for the life of your project, from design to delivery."
    },
    {
      "statement": "Online customer interaction is limited to a basic web form without live status tracking, self-service quoting, or scheduling tools.",
      "label": "inference",
      "sourceUrl": "https://www.boisemetalworks.com/contact/",
      "quote": null
    }
  ],
  "problems": [
    {
      "problem": "Manual intake and estimation bottlenecks for custom CAD drawings and project specifications.",
      "label": "hypothesis",
      "basis": "Inquiries permit unstructured file uploads up to 16MB which typically require manual review by estimators or shop drafters before quoting."
    },
    {
      "problem": "Potential delay in quoting turnaround without automated acknowledgment or CRM lead routing.",
      "label": "hypothesis",
      "basis": "Web inquiries submit to a standard WordPress Contact Form 7 endpoint without observable automated quoting or customer portal systems."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Job shop ERP and manufacturing software (e.g., JobBOSS², E2 Shop System, or Genius ERP)",
      "addresses": "Estimating, job costing, routing, bill of materials, and shop capacity scheduling for custom metal fabrication.",
      "alreadyOwned": false
    },
    {
      "solution": "Manufacturing CRM and lead tracking software (e.g., HubSpot or Pipedrive)",
      "addresses": "Tracking contractor bidding requests, following up on pending quotes, and centralizing client project communications.",
      "alreadyOwned": false
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "No ForgeX solutions are recommended because Boise Metal Works is outside ForgeX's target market of owner-led home-service contractors (HVAC, plumbing, electrical). ForgeX's productized pipeline, dispatch, and field-service software integrations do not match the workflow of a custom industrial/commercial metal fabrication shop."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "Custom metal fabrication requires manual review of structural blueprints, material specifications, tolerances, and machinery limitations, which falls outside the scope of ForgeX's AI service catalog."
  },
  "humanReview": [
    "Qualified drafters and estimators must review engineering drawings and specifications for structural and safety compliance.",
    "Shop supervisors must inspect material availability, machine tooling capacities, and weld procedures before committing to production schedules."
  ],
  "risks": [
    {
      "type": "operational",
      "description": "Metal fabrication projects involve structural safety and building code standards; attempting automated quotation or specification intake without engineering review risks structural defects and liability."
    },
    {
      "type": "operational",
      "description": "ForgeX does not specialize in manufacturing ERP, CAD/CAM nesting pipelines, or fabrication job-costing systems."
    },
    {
      "type": "security",
      "description": "Accepting arbitrary file uploads up to 16MB through web forms requires rigorous scanning against malware and secure handling of proprietary client designs."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": [
      "No commercial projection is modeled because the prospect is not within ForgeX's target contractor vertical, and no ForgeX solutions are offered."
    ]
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner / Principal",
      "General Manager / Vice President",
      "Shop Operations Manager",
      "Lead Estimator / Project Manager"
    ],
    "people": [],
    "channels": [
      {
        "kind": "phone",
        "value": "[redacted]",
        "sourceUrl": "https://www.boisemetalworks.com/"
      },
      {
        "kind": "web form",
        "value": "https://www.boisemetalworks.com/contact/",
        "sourceUrl": "https://www.boisemetalworks.com/contact/"
      }
    ]
  },
  "discovery": {
    "questions": [
      "How does your team currently manage CAD and blueprint intake from the initial web inquiry through estimating to the shop floor?",
      "What software do you rely on to manage job routing, material costing, and shop schedule tracking across your shearing, forming, and water jet operations?",
      "What share of your revenue is generated from recurring commercial contractor bids versus one-off residential projects?"
    ],
    "outreachSubject": "",
    "outreachBody": ""
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://www.boisemetalworks.com/",
        "usedFor": "Business identity, physical location, service lines, contact information, and footer copyright."
      },
      {
        "url": "https://www.boisemetalworks.com/idaho-master-metal-fabricators-history/",
        "usedFor": "Company founding year (1994) and organizational background."
      },
      {
        "url": "https://www.boisemetalworks.com/contact/",
        "usedFor": "Contact form details, file upload capabilities, and office address."
      },
      {
        "url": "https://www.boisemetalworks.com/metals-fabrication-industry-infomation/",
        "usedFor": "Shop hourly billing rate ($95/hr), building code references, and material capabilities."
      },
      {
        "url": "https://www.boisemetalworks.com/services/",
        "usedFor": "Overview of fabrication service categories."
      },
      {
        "url": "https://www.boisemetalworks.com/metal-fabrication-shop-capacities/",
        "usedFor": "Machinery specifications, welding capabilities, and nesting software usage."
      },
      {
        "url": "https://www.boisemetalworks.com/product-development-manufacturing/",
        "usedFor": "Value engineering and manufacturing support services for contractors."
      }
    ],
    "limitations": [
      "The website does not state total employee count to verify if staff is within the 10-75 range.",
      "The website does not present current owners, executives, or managers with active job titles.",
      "The website does not disclose state contractor licensing IDs or formal business registration numbers.",
      "The website shows no customer acquisition ad spend or field-service management platform usage."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "ForgeX targets owner-led home-service contractors (HVAC, plumbing, and electrical) with 10 to 75 staff who pay for leads and utilize field-service management platforms. Boise Metal Works is a custom metal fabrication and industrial manufacturing job shop offering machining, water jet cutting, structural fabrication, railings, stairs, tanks, and truck upfitting for commercial, industrial, and residential clients. Because it is outside the mechanical home-services sector and does not operate a residential field-dispatch model, it does not fit ForgeX's offerings."
  }
}
